<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><script type="text/javascript" src="{pigcms{$static_public}js/layer/layer.js"></script><style>    .layui-layer-dialog {        top: 100px !important;    }</style>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Employee/employee_memory_list')}" class="on">从业人员标签</a>                    <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/memory_add')}','添加标签',580,460,true,false,false,addbtn,'add',true);">添加标签</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Employee/employee_memory_list')}" method="get">							<input type="hidden" name="c" value="Employee"/>							<input type="hidden" name="a" value="employee_memory_list"/><!--							筛选: --><!--							<if condition="$admin_area neq 3">--><!--							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" style="display:inline"></div>--><!--							</if>--><!--							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>--><!--							<select name="searchtype">--><!--								<option value="true_name" <if condition="$_GET['searchtype'] eq 'true_name'">selected="selected"</if>>姓名</option>--><!--								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>--><!--								<!-- <option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option> --><!--							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-->														状态:							<select name="status">								<option value="" <if condition="$_GET['status'] eq ''">selected="selected"</if>>全部</option>								<option value="0" <if condition="$_GET['status'] eq '0'">selected="selected"</if>>开启</option>								<option value="1" <if condition="$_GET['status'] eq '1'">selected="selected"</if>>禁止</option>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						</form>											</td>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>标签名称</th>								<th>标签备注</th>								<th>被关联标记数</th>								<th>排序值</th>								<th>添加时间</th>								<th>状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($employee_memory_list)">								<volist name="employee_memory_list" id="vo">									<tr>										<td>{pigcms{$vo.memory_id}</td>										<td>{pigcms{$vo.memory_name}</td>										<td>{pigcms{$vo.memory_remark}</td>										<td>{pigcms{$vo.num} | <a href="{pigcms{:U('Employee/employee_memory_user', array('memory_id'=>$vo['memory_id']))}">明细</a></td>										<td>{pigcms{$vo.sort}</td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										<td>											<span class="cb-enable"><label class="cb-enable <if condition="$vo['status'] eq 0">selected</if>"><span onclick="infoSwitch('{pigcms{$vo.memory_id}', 0)" >开启</span><input type="radio" value="0" <if condition="$vo['status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['status'] eq 1">selected</if>"><span onclick="infoSwitch('{pigcms{$vo.memory_id}', 1)">禁止</span><input type="radio" value="1" <if condition="$vo['status'] eq 1">checked="checked"</if> /></label></span>										</td>										<td class="textcenter">										 <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/memory_edit',array('memory_id'=>$vo['memory_id']))}','编辑信息',560,450,true,false,false,editbtn,'edit',true);">编辑</a>&nbsp; | &nbsp;<a href="javascript:void(0);" onclick="toDelItem({pigcms{$vo.memory_id});">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>		</div><script>    var lockInfo = false;    function infoSwitch(memory_id, status) {        if (lockInfo) return;        lockInfo = true;        var switch_memory_status = "{pigcms{:U('Employee/switch_memory_status')}";        $.post(switch_memory_status,{memory_id:memory_id,'status': status},function(data){            console.log('data', data);            if (data && (data.status === 1 || data.status === '1')) {                location.reload();            } else {                alert(data.info)            }        },'json');        setTimeout(function(){            lockInfo = false;        },1000);    }    function toDelItem(memory_id) {        if (lockInfo) return;        lockInfo = true;        layer.open({            title:['提示','background-color:#FF658E;color:#fff;'],            content:'是否确认删除',            shadeClose:false,            btn: ['确定', '取消'],            yes:function(){                var memory_url = "{pigcms{:U('Employee/del_memory')}";                $.post(memory_url,{'memory_id':memory_id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        });        setTimeout(function(){            lockInfo = false;        },1000);    }</script><include file="Public:footer"/>